using namespace std;
int n, best = 0;
vector<string> w;
int used_[25], ovl[25][25];
int overlap(const string &a, const string &b) {
    int lim = min(a.size(), b.size()) - 1;
    for (int l = 1; l <= lim; l++) {
        bool ok = true;
        for (int i = 0; i < l; i++) if (a[a.size()-l+i] != b[i]) { ok = false; break; }
        if (ok) return l;
    }
    return 0;
}
void dfs(int len, int last) {
    best = max(best, len);
    for (int j = 0; j < n; j++)
        if (used_[j] < 2 && ovl[last][j] > 0) {
            used_[j]++;
            dfs(len + (int)w[j].size() - ovl[last][j], j);
            used_[j]--;
        }
}
int main() {
    cin >> n;
    w.resize(n);
    for (auto &s : w) cin >> s;
    char st; cin >> st;
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) ovl[i][j] = overlap(w[i], w[j]);
    for (int i = 0; i < n; i++)
        if (w[i][0] == st) {
            used_[i] = 1;
            dfs(w[i].size(), i);
            used_[i] = 0;
        }
    cout << best << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
long long divsum(long long x) {
    if (x <= 1) return 0;
    long long s = 1;
    for (long long d = 2; d * d <= x; d++)
        if (x % d == 0) { s += d; if (d * d != x) s += x / d; }
    return s;
}
int main() {
    long long a, b;
    cin >> a >> b;
    cout << (divsum(a) == b && divsum(b) == a ? "yes" : "no") << endl;
    return 0;
}

